import { describe, expect, it } from 'vitest';
import { configureAndroidSigning } from './gradle';

const template = `android {
    signingConfigs {
        debug { storePassword 'android' }
    }
    buildTypes {
        debug {
            signingConfig signingConfigs.debug
        }
        release {
            // Generated by Expo.
            signingConfig signingConfigs.debug
        }
    }
}`;

describe('Android release signing', () => {
  it('keeps debug signing for debug builds and uses the upload identity for releases', () => {
    const result = configureAndroidSigning(template);
    expect(result).toContain('debug {\n            signingConfig signingConfigs.debug');
    expect(result).toContain('signingConfig kromaHasSigning ? signingConfigs.kromaUpload');
    expect(result).toContain("System.getenv('KROMA_ANDROID_KEYSTORE_PASSWORD')");
    expect(configureAndroidSigning(result)).toBe(result);
  });

  it('guards against partial credentials and debug-signed Play bundles', () => {
    const result = configureAndroidSigning(template);
    expect(result).toContain('&& !kromaHasSigning');
    expect(result).toContain("it.name == 'bundleRelease'");
    expect(result).toContain('A Play app bundle requires');
  });

  it('fails when the generated release signing template is no longer recognized', () => {
    expect(() => configureAndroidSigning('android {}')).toThrow(/template changed/);
  });
});
